import {HiveScene} from './scene.js';
import {zones,cells,journey,questions,sources,t} from './content.js';
import {progress,reward,save,badges} from './state.js';
import {askBuzz} from './buzz.js';
const $=s=>document.querySelector(s),ui=$('#ui');let mode='home',selected=null,cellIndex=0,journeyIndex=0,missionVisited=new Set(),missionBusy=false,missionDone=false,quizIndex=0,quizScore=0,quizAnswer=null,quizFinished=false,entering=false,toastTimer,mutedHud=false;
const navModes=[['home','Home','⌂'],['explore','Explore hive','⬡'],['cells','Cell explorer','◎'],['mission','Pollination','✿'],['journey','Honey journey','◈'],['quiz','Bee quiz','?'],['achievements','Achievements','✧'],['about','About bees','↗']];
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function earn(id,amount){if(reward(id,amount)){toast(`+${amount} XP · ${id==='all'?'Hive Explorer unlocked':id==='mission'?'Pollination Hero unlocked':id==='quiz'?'Bee Guardian unlocked':'Discovery saved'}`);audio.chime();}}
const scene=new HiveScene($('#world'),{onSelect:selectZone,onFlower:visitFlower,onReady:()=>{const bar=$('#loading progress');bar.value=100;setTimeout(()=>$('#loading').classList.add('loaded'),650);},onFallback:()=>{document.body.classList.add('no-webgl');toast('3D is unavailable on this device. All learning modes remain accessible.');}});
function dock(){return `<div class="mode-dock glass" aria-label="Experience modes">${navModes.filter(x=>x[0]!=='home'&&x[0]!=='about').map(([id,label,icon])=>`<button data-mode="${id}" class="${mode===id?'active':''}" aria-label="${label}"><span>${icon}</span><small>${label}</small></button>`).join('')}</div>`;}
function hud(){return `<div class="hud glass"><button data-mode="achievements"><span class="gold">✧</span> <b>${progress.xp}</b> XP</button><span>LEVEL ${1+Math.floor(progress.xp/150)}</span><span>${progress.discovered.length}/6 DISCOVERED</span></div>`;}
function panelTop(k,title){return `<span class="eyebrow">${k}</span><h1>${title}</h1>`;}
function render(){document.body.dataset.mode=mode;$('#footer').style.display=mode==='home'?'flex':'none';$('#camera-controls').style.display=mode==='home'?'none':'flex';$('#hotspots').innerHTML='';let html='';
 if(mode==='home')html=`<section class="hero"><div class="edition"><span></span> A LIVING WORLD, WAITING TO BE DISCOVERED</div><h1>Enter a world<br><em>worth protecting.</em></h1><p class="tagline">Step Inside. Discover. Protect.</p><p class="hero-copy">Follow the light into a honey-bee colony.<br>Discover extraordinary lives behind every<br>drop of honey.</p><div class="hero-actions"><button class="primary" id="enter">${t(progress.language,'enter')} <span>↗</span></button><button class="text-button" id="features">Explore features <span>↓</span></button></div><div class="hero-note"><span class="tiny-hex">⬡</span> An interactive natural-history experience.</div></section><div class="scene-caption glass"><span class="status-dot"></span><div><span class="eyebrow">APIS MELLIFERA</span><p>One colony. Thousands of stories.</p></div><span>01 / 06</span></div><div class="side-label">NATURE, FROM A NEW PERSPECTIVE</div><div class="home-coordinate">THE HIVE<br><span>YOUR JOURNEY STARTS HERE</span><i></i></div>`;
 else if(mode==='explore'){html=`<section class="mode-heading">${panelTop('THE LIVING COLONY','Explore the hive')}<p>Every bee has a part to play. Find their stories.</p></section>${hud()}<aside class="explore-list glass"><span class="eyebrow">YOUR FIELD NOTES</span>${Object.entries(zones).map(([id,z])=>`<button data-zone="${id}" class="${selected===id?'selected':''}"><span>${z.icon}</span>${z.name}<small>${progress.discovered.includes(id)?'✓':'↗'}</small></button>`).join('')}<p>Drag to orbit · Scroll to zoom</p></aside>${selected?`<article class="info-panel glass"><button class="close" id="back-hive" aria-label="Back to hive">×</button><span class="eyebrow">${zones[selected].sub}</span><h2>${zones[selected].name}</h2><p>${zones[selected].description}</p><ul>${zones[selected].facts.map(x=>`<li>${x}</li>`).join('')}</ul><button class="primary" id="ask-context">Ask Buzz about this ↗</button><button class="text-button" id="back-hive-bottom">← Back to hive</button></article>`:'<div class="world-hint">SELECT A BEE. DISCOVER A STORY.</div>'}`;}
 else if(mode==='cells')html=`<section class="mode-heading">${panelTop('A CLOSER LOOK','Life inside a cell')}<p>From a single egg to a life of extraordinary work.</p></section>${hud()}<article class="info-panel glass cell-panel"><span class="eyebrow">${cells[cellIndex].time}</span><h2>${cells[cellIndex].name}</h2><p>${cells[cellIndex].text}</p><small class="muted">Worker-bee timeline · approximate development</small><div class="cell-tabs">${cells.map((c,i)=>`<button data-cell="${i}" class="${i===cellIndex?'active':''}">${c.name}</button>`).join('')}</div></article><div class="timeline glass">${cells.slice(0,4).map((c,i)=>`<button data-cell="${i}" class="${i===cellIndex?'active':''}"><span class="stage-hex">${['Ⅰ','Ⅱ','Ⅲ','Ⅳ'][i]}</span><b>${['Egg','Larva','Pupa','Adult bee'][i]}</b><small>${c.time}</small></button>`).join('')}</div>`;
 else if(mode==='mission')html=`<section class="mode-heading">${panelTop('POLLINATION MISSION',missionDone?'A little flight. A big impact.':'Follow the flowers.')}<p>${missionDone?'You helped pollinate the ecosystem.':'Guide your worker to five different flowers, then fly home.'}</p></section>${hud()}<article class="mission-panel glass"><span class="eyebrow">${missionDone?'MISSION COMPLETE':'YOUR FORAGING FLIGHT'}</span><h2>${missionDone?'Pollination hero':'Make every visit count'}</h2><div class="metric"><span>Flowers visited</span><b>${missionVisited.size} / 5</b></div><progress value="${missionVisited.size}" max="5" aria-label="Flowers visited"></progress><div class="metric"><span>Pollen collected</span><b>${missionVisited.size*20}%</b></div><div class="metric"><span>Nectar collected</span><b>${missionVisited.size*20}%</b></div><p class="muted">Simplified learning simulation. Each visit transfers pollen and collects food.</p><div class="flower-buttons">${[0,1,2,3,4].map(i=>`<button data-flower="${i}" ${missionBusy||missionDone||missionVisited.has(i)?'disabled':''}>✿ ${i+1}${missionVisited.has(i)?' ✓':''}</button>`).join('')}</div>${missionDone?`<p class="gold">✧ 100 XP · Pollination Hero</p><button class="primary" id="restart-mission">Fly again ↗</button>`:`<button class="primary" id="return-home" ${missionVisited.size<5||missionBusy?'disabled':''}>Return to the hive ↗</button>`}</article>`;
 else if(mode==='journey')html=`<section class="mode-heading">${panelTop('NECTAR TO HONEY','A taste of teamwork.')}<p>Follow eight small steps behind every drop.</p></section>${hud()}<article class="info-panel glass"><span class="eyebrow">STEP ${journeyIndex+1} OF 8</span><h2>${journey[journeyIndex][0]}</h2><p>${journey[journeyIndex][1]}</p><div class="journey-visual" aria-label="Animated honey production process">${['✿ → ✦','✿ · · ✦','✦ → ⬡','✦ ⇄ ✦','≋ ↑ ≋','◈ → ◆','◆ → ⬡','⬡ → ⬢'][journeyIndex]}</div><progress max="8" value="${journeyIndex+1}" aria-label="Honey journey progress"></progress><div class="row"><button id="journey-prev" class="secondary" ${journeyIndex===0?'disabled':''}>← Previous</button><button id="journey-next" class="primary">${journeyIndex===7?'Finish journey ✓':'Next step →'}</button></div></article><div class="journey-steps glass">${journey.map((s,i)=>`<button data-step="${i}" aria-label="Step ${i+1}: ${s[0]}" class="${journeyIndex===i?'active':''}">${i+1}</button>`).join('')}</div>`;
 else if(mode==='quiz'){const q=questions[quizIndex];html=`<section class="quiz-panel glass">${panelTop('THE BEE QUIZ',quizFinished?'Knowledge takes flight.':'How well do you know the hive?')}${quizFinished?`<p class="score">${quizScore}<span>/10</span></p><p>${quizScore>=8?'A remarkable result, bee guardian.':'Every discovery counts. Keep exploring and try again.'}</p><p class="gold">✧ Quiz completed · 50 XP reward (once)</p><p>Best score: ${progress.bestScore} / 10</p><div class="row"><button class="primary" id="restart-quiz">Restart quiz ↗</button><button class="secondary" data-mode="achievements">View achievements</button></div>`:`<div class="metric"><span>QUESTION ${quizIndex+1} / 10</span><span>${quizScore} CORRECT</span></div><progress max="10" value="${quizIndex+1}" aria-label="Quiz progress"></progress><h2>${q[0]}</h2><div class="answers">${q[1].map((a,i)=>`<button data-answer="${i}" class="${quizAnswer!==null?(i===q[2]?'correct':i===quizAnswer?'wrong':''):''}" ${quizAnswer!==null?'disabled':''}><span>⬡</span><b>${String.fromCharCode(65+i)}</b>${a}</button>`).join('')}</div>${quizAnswer!==null?`<div class="feedback" role="status"><b>${quizAnswer===q[2]?'Correct. Nicely spotted!':'A new thing learned.'}</b><p>${q[3]}</p></div><button class="primary" id="next-question">${quizIndex===9?'See your results':'Next question'} →</button>`:'<p class="muted">Choose one answer to continue.</p>'}`}</section>${hud()}`;}
 else if(mode==='achievements')html=`<section class="wide-panel glass">${panelTop('YOUR EXPLORER JOURNAL','Small discoveries. Lasting impact.')}<div class="achievement-summary"><div><strong>${progress.xp}</strong><span>TOTAL XP</span></div><div><strong>${1+Math.floor(progress.xp/150)}</strong><span>EXPLORER LEVEL</span></div><div><strong>${progress.discovered.length}/6</strong><span>HIVE ZONES</span></div></div><div class="badges">${badges.map(([name,desc,id,icon])=>`<div class="badge ${progress.rewards.includes(id)?'unlocked':''}"><span>${icon}</span><h3>${name}</h3><p>${desc}</p><small>${progress.rewards.includes(id)?'UNLOCKED':'YET TO DISCOVER'}</small></div>`).join('')}</div><p class="muted">Progress is saved on this device. Explore all six zones for a 150 XP bonus. Discovery rewards are awarded once.</p><button class="primary" data-mode="explore">Continue exploring ↗</button></section>`;
 else if(mode==='about')html=`<section class="wide-panel about-panel glass">${panelTop('OUR WORLD IS CONNECTED','Protect the pollinators.<br><em>Protect our future.</em>')}<p>Each flower visit is part of a bigger story. Pollinators help flowering plants reproduce, supporting food production, biodiversity and entire ecosystems.</p><p>Honey bees are important managed crop pollinators. Native bees and other wild pollinators have their own irreplaceable roles. Plant diverse, locally appropriate flowers, protect nesting places and avoid unnecessary pesticide use.</p><div class="future-grid"><article><span class="eyebrow">AR HIVE — FUTURE EXPERIENCE</span><h3>A hive on your table.</h3><p>A future WebXR module could place this colony in your room. AR is not enabled in this prototype.</p></article><article><span class="eyebrow">LIVE HIVE · SIMULATION / DEMO DATA</span><h3>A window into the real world.</h3><p>Real hive → Sensors → Cloud → HIVEVERSE</p><div class="sample-data"><span>Temperature <b>34.5°C</b></span><span>Humidity <b>58%</b></span><span>Hive weight <b>28.4 kg</b></span><span>Activity <b>Moderate</b></span></div></article></div><div class="sources"><span class="eyebrow">CONTINUE YOUR DISCOVERY</span>${sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}</div></section>`;
 ui.innerHTML=html+(mode==='home'?'':dock());bind();if(mode==='explore'&&!selected)makeHotspots();if(mode==='mission'&&!missionDone)makeFlowerHotspots();
 }
 function go(next){if(entering)return;mode=next;selected=null;mutedHud=false;document.body.classList.remove('hud-collapsed');scene.setMode(next);if(next==='cells')scene.showCell(cellIndex);if(next==='journey')scene.journeyStep(journeyIndex);render();$('#mobile-nav')?.remove();$('#menu').setAttribute('aria-expanded','false');}
 function selectZone(id){if(!zones[id])return;selected=id;if(mode!=='explore'){mode='explore';scene.setMode(mode);}if(!progress.discovered.includes(id)){progress.discovered.push(id);save();earn(id,20);if(progress.discovered.length===6)earn('all',150);}scene.select(id);render();contextMessage(id);}
 function bind(){ui.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>go(b.dataset.mode));ui.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>selectZone(b.dataset.zone));ui.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{cellIndex=Number(b.dataset.cell);scene.showCell(cellIndex);render();});ui.querySelectorAll('[data-flower]').forEach(b=>b.onclick=()=>visitFlower(Number(b.dataset.flower)));ui.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{journeyIndex=Number(b.dataset.step);scene.journeyStep(journeyIndex);render();});ui.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(quizAnswer!==null)return;quizAnswer=Number(b.dataset.answer);if(quizAnswer===questions[quizIndex][2])quizScore++;render();});
 const on=(id,f)=>{const el=$(id);if(el)el.onclick=f;};on('#enter',async()=>{entering=true;$('#enter').disabled=true;$('#enter').textContent='Following the colony…';document.body.classList.add('entering');await scene.enter();entering=false;document.body.classList.remove('entering');mode='explore';render();});on('#features',()=>go('explore'));on('#back-hive',()=>{selected=null;scene.reset();render();});on('#back-hive-bottom',()=>{selected=null;scene.reset();render();});on('#ask-context',()=>openBuzz());on('#return-home',()=>{if(missionVisited.size!==5||missionBusy)return;scene.returnHome();missionDone=true;earn('mission',100);render();});on('#restart-mission',()=>{missionVisited.clear();missionDone=false;render();});on('#journey-prev',()=>{journeyIndex=Math.max(0,journeyIndex-1);scene.journeyStep(journeyIndex);render();});on('#journey-next',()=>{if(journeyIndex===7){earn('journey',50);go('achievements');}else{journeyIndex++;scene.journeyStep(journeyIndex);render();}});on('#next-question',()=>{if(quizIndex===9){quizFinished=true;progress.bestScore=Math.max(progress.bestScore,quizScore);save();earn('quiz',50);}else{quizIndex++;quizAnswer=null;}render();});on('#restart-quiz',()=>{quizIndex=0;quizScore=0;quizAnswer=null;quizFinished=false;render();});}
 async function visitFlower(i){if(mode!=='mission'||missionBusy||missionDone||missionVisited.has(i)||i<0||i>4)return;missionBusy=true;render();await scene.flyToFlower(i);missionVisited.add(i);missionBusy=false;if(mode==='mission')render();toast(missionVisited.size===5?'Five flowers visited. Bring your harvest home!':`Flower ${i+1} pollinated · nectar collected`);}
 function makeHotspots(){$('#hotspots').innerHTML=Object.entries(zones).map(([id,z])=>`<button class="hotspot" data-hotspot="${id}"><i></i>${z.name}<span>↗</span></button>`).join('');$('#hotspots').querySelectorAll('button').forEach(b=>b.onclick=()=>selectZone(b.dataset.hotspot));}
 function makeFlowerHotspots(){$('#hotspots').innerHTML=[0,1,2,3,4].map(i=>`<button class="hotspot flower-hotspot" data-flower-hotspot="${i}" ${missionBusy||missionVisited.has(i)?'disabled':''}><i></i>Flower ${i+1}${missionVisited.has(i)?' ✓':' ↗'}</button>`).join('');$('#hotspots').querySelectorAll('button').forEach(b=>b.onclick=()=>visitFlower(Number(b.dataset.flowerHotspot)));}
 scene.onFrame=()=>{$('#hotspots').querySelectorAll('button').forEach(b=>{const p=b.dataset.hotspot?zones[b.dataset.hotspot].position:scene.flowers[Number(b.dataset.flowerHotspot)].position.toArray().map((x,i)=>i===1?x+1:x);const s=scene.project(p);if(s){b.style.left=s.x+'px';b.style.top=s.y+'px';b.style.visibility=s.visible&&s.x>55&&s.x<innerWidth-55&&s.y>185&&s.y<innerHeight-(innerWidth<760?240:115)?'visible':'hidden';}});};
 document.querySelectorAll('header [data-mode]').forEach(b=>b.onclick=()=>go(b.dataset.mode));$('#zoom-in').onclick=()=>scene.zoom(.8);$('#zoom-out').onclick=()=>scene.zoom(1.25);$('#reset-camera').onclick=()=>scene.reset();$('#collapse-hud').onclick=()=>{mutedHud=!mutedHud;document.body.classList.toggle('hud-collapsed',mutedHud);};$('#help').onclick=()=>$('#help-dialog').showModal();$('#help-dialog .close').onclick=$('#help-dialog .close-help').onclick=()=>$('#help-dialog').close();
 $('#menu').onclick=()=>{const old=$('#mobile-nav');if(old){old.remove();$('#menu').setAttribute('aria-expanded','false');return;}const nav=document.createElement('nav');nav.id='mobile-nav';nav.className='glass';nav.innerHTML=navModes.map(([id,label])=>`<button data-mode="${id}">${label}</button>`).join('')+'<button id="nav-buzz">Buzz AI</button>';document.body.append(nav);nav.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>go(b.dataset.mode));$('#nav-buzz').onclick=()=>{openBuzz();nav.remove();};$('#menu').setAttribute('aria-expanded','true');};
 $('#language').value=progress.language;$('#language').onchange=e=>{progress.language=e.target.value;save();document.documentElement.lang='en';render();toast(progress.language==='en'?'English selected':'Language preview selected. Learning content falls back to English.');};
 function addChat(text,role='buzz'){const p=document.createElement('p');p.className=role;p.textContent=text;$('#chat').append(p);$('#chat').scrollTop=$('#chat').scrollHeight;}
 function contextMessage(id){$('#chat').replaceChildren();addChat(`You found ${id==='queen'?'the queen':zones[id].name.toLowerCase()}. ${zones[id].description}`);$('#suggestions').innerHTML=(id==='queen'?['How many eggs can she lay?','How is a queen created?','What happens when she dies?']:['Tell me more','How is honey made?','Why are bees important?']).map(s=>`<button>${s}</button>`).join('');$('#suggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>sendQuestion(b.textContent));}
 function openBuzz(){$('#buzz-panel').hidden=false;$('#buzz-launch').hidden=true;if(!$('#chat').children.length)contextMessage(selected||'queen');$('#buzz-input').focus();}
 async function sendQuestion(q){addChat(q,'user');const response=await askBuzz(q,selected||'queen');addChat(response);}
 $('#buzz-launch').onclick=openBuzz;$('#buzz-close').onclick=()=>{$('#buzz-panel').hidden=true;$('#buzz-launch').hidden=false;$('#buzz-launch').focus();};$('#buzz-form').onsubmit=e=>{e.preventDefault();const input=$('#buzz-input'),q=input.value.trim();if(q){input.value='';sendQuestion(q);}};
 class AudioManager{constructor(){this.context=null;this.gain=null;this.active=false;}async toggle(){if(!this.context){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){toast('Audio is not supported in this browser.');return;}this.context=new Audio();this.gain=this.context.createGain();this.gain.gain.value=0;this.gain.connect(this.context.destination);[116,121,232].forEach((hz,i)=>{const osc=this.context.createOscillator();osc.type='sine';osc.frequency.value=hz;const g=this.context.createGain();g.gain.value=i===2?.06:.12;osc.connect(g).connect(this.gain);osc.start();});}await this.context.resume();this.active=!this.active;this.gain.gain.setTargetAtTime(this.active?.16:0,this.context.currentTime,.4);progress.sound=this.active;save();$('#sound').classList.toggle('active',this.active);$('#sound').setAttribute('aria-label',`Turn ambient sound ${this.active?'off':'on'}`);toast(this.active?'Ambient hive sound on':'Sound off');}chime(){if(!this.active)return;const o=this.context.createOscillator(),g=this.context.createGain();o.frequency.value=660;g.gain.setValueAtTime(.06,this.context.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.context.currentTime+.4);o.connect(g).connect(this.context.destination);o.start();o.stop(this.context.currentTime+.4);}}
 const audio=new AudioManager();$('#sound').onclick=()=>audio.toggle().catch(()=>toast('Audio could not start. Try again.'));
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#buzz-panel').hidden=true;$('#buzz-launch').hidden=false;$('#mobile-nav')?.remove();if(mutedHud){mutedHud=false;document.body.classList.remove('hud-collapsed');}}});
 render();
 // Future integrations: supply server-side providers without coupling the educational UI to hardware.
 export const integrations={ar:{enabled:false,async supported(){return !!(await navigator.xr?.isSessionSupported?.('immersive-ar'));}},digitalTwin:{kind:'simulation',async read(){return {temperature:34.5,humidity:58,weight:28.4,activity:'moderate',simulated:true};}}};
 if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'navigate_hive',description:'Open a HIVEVERSE learning mode without completing it.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:navModes.map(x=>x[0])}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!navModes.some(x=>x[0]===input.mode))throw new Error('Unknown mode');go(input.mode);return {mode};}});}catch{/* Experimental browser API is optional. */}}
